const publisherConfig = {"allowedUserIds":[6729441444],"allowedChatIds":[6729441444],"channelId":"6ae04e2c2f1f5ed648e6e5cc","publicBaseUrl":"https://parent-duck-lines-muscle.trycloudflare.com","services":["tiktok","facebook","threads"],"albumQuietMs":3000,"mediaWebhookId":"72b6fa94-2772-4442-bd42-5b4d07e37206"};
const fs = require('fs');
const crypto = require('crypto');
const context = $('Assemble Media').first().json;
const response = $input.first().json;
if (response.errors?.length || !Array.isArray(response.data?.channels)) return [{ json: { ...context, shouldCreate: false, preparationError: 'Chưa đọc được các kênh đã kết nối. Bài chưa được gửi đăng.' } }];
const targets = [];
for (const service of publisherConfig.services) {
  const channels = response.data.channels.filter((channel) => channel.service === service);
  for (const channel of channels.length ? channels : [{ id: 'missing-' + service, name: '', service, missing: true }]) {
    const targetFile = `/files/telegram-target-${crypto.createHash('sha256').update(context.journalFile + ':' + channel.id).digest('hex')}.json`;
    const blocked = channel.missing || channel.isDisconnected || channel.isLocked;
    const captionLength = Array.from(context.caption).length;
    const exceedsThreadsLimit = service === 'threads' && captionLength > 499;
    const target = { ...context, channelId: channel.id, channelName: channel.name, service, targetFile, metadata: service === 'facebook' ? { facebook: { type: 'post' } } : service === 'tiktok' ? context.metadata : {}, shouldCreate: !blocked && !exceedsThreadsLimit, status: blocked ? 'unavailable' : exceedsThreadsLimit ? 'skipped' : 'submitting', error: channel.missing ? 'Chưa kết nối trong Buffer.' : blocked ? 'Kênh bị ngắt kết nối hoặc bị khóa.' : exceedsThreadsLimit ? `Caption có ${captionLength} ký tự, vượt mức tối đa 499 ký tự đã cấu hình. Chưa gửi đăng Threads; hãy rút gọn caption.` : undefined };
    try { fs.writeFileSync(targetFile, JSON.stringify(target), { flag: 'wx', mode: 0o600 }); }
    catch (error) { if (error.code !== 'EEXIST') throw error; target.shouldCreate = false; }
    targets.push(target);
  }
}
const saved = JSON.parse(fs.readFileSync(context.journalFile, 'utf8'));
fs.writeFileSync(context.journalFile, JSON.stringify({ ...saved, caption: context.caption, mediaCount: context.assets.length, targets: targets.map((target) => target.targetFile), status: 'processing' }));
const requests = targets.filter((target) => target.shouldCreate);
return requests.length ? requests.map((json) => ({ json, pairedItem: { item: 0 } })) : [{ json: { ...context, shouldCreate: false } }];

const resultSource = 'Build Targets';
return $input.all().map((item, index) => {
  const context = $(resultSource).itemMatching(index).json;
  const response = item.json;
  const created = response.data?.createPost;
  const post = created ? created.post : response.data?.post;
  const error = response.error ? 'Không xác nhận được kết quả từ API. Không tự gửi lại.' : response.errors?.map((entry) => entry.message).join('\n') ??
    (created && created.__typename !== 'PostActionSuccess' ? created.message ?? created.__typename : post?.error?.message);
  return { json: { ...context, postId: post?.id ?? context.postId, status: response.error || response.errors?.length ? 'unknown' : created && created.__typename !== 'PostActionSuccess' ? 'rejected' : post?.status ?? 'unknown', externalLink: post?.externalLink, error }, pairedItem: { item: index } };
});

const fs = require('fs');
const crypto = require('crypto');
for (const item of $input.all()) {
  const saved = JSON.parse(fs.readFileSync(item.json.targetFile, 'utf8'));
  const result = { ...item.json, updatedAt: new Date().toISOString() };
  // A concurrent, older status response must not downgrade an already sent post.
  if (saved.status === 'sent' && result.status !== 'sent') continue;
  const temp = item.json.targetFile + '.' + crypto.randomBytes(8).toString('hex') + '.tmp';
  fs.writeFileSync(temp, JSON.stringify(result), { mode: 0o600 });
  fs.renameSync(temp, item.json.targetFile);
}
return $input.all();

const fs = require('fs');
const crypto = require('crypto');
const context = $input.first().json;
const saved = JSON.parse(fs.readFileSync(context.journalFile, 'utf8'));
const targets = (saved.targets ?? []).map((file) => JSON.parse(fs.readFileSync(file, 'utf8')));
const labels = { tiktok: 'TikTok', facebook: 'Facebook Page', instagram: 'Instagram', threads: 'Threads' };
const titles = { sent: 'Đã đăng', error: 'Đăng thất bại', rejected: 'Bị từ chối', skipped: 'Bỏ qua, chưa gửi đăng', unavailable: 'Chưa sẵn sàng', sending: 'Đang đăng', scheduled: 'Đang chờ đăng', submitting: 'Chưa xác nhận kết quả', unknown: 'Chưa xác nhận kết quả', draft: 'Bản nháp, chưa đăng', needs_approval: 'Cần duyệt, chưa đăng' };
const pending = targets.some((target) => target.postId && ['sending', 'scheduled', 'submitting'].includes(target.status));
const text = context.preparationError ?? (targets.length ? 'Kết quả bài đăng:\n' + targets.map((target) => `${labels[target.service] ?? target.service}${target.channelName ? ' (' + target.channelName + ')' : ''}: ${titles[target.status] ?? target.status}${target.error ? ' — ' + target.error : ''}${target.externalLink ? '\n' + target.externalLink : ''}`).join('\n\n') : context.failureMessage ?? 'Chưa có kết quả đăng.');
const status = targets.length && targets.every((target) => target.status === 'sent') ? 'sent' : pending ? 'processing' : targets.some((target) => target.status === 'sent') ? 'partial' : 'error';
const receipt = { ...saved, status, text, updatedAt: new Date().toISOString() };
const temp = context.journalFile + '.' + crypto.randomBytes(8).toString('hex') + '.tmp';
fs.writeFileSync(temp, JSON.stringify(receipt), { mode: 0o600 });
fs.renameSync(temp, context.journalFile);
return [{ json: { chatId: saved.chatId, messageId: saved.messageId, journalFile: context.journalFile, queryStatus: context.queryStatus, status, text, shouldPoll: pending && $runIndex < 12 } }];

const fs = require('fs');
const context = $input.first().json;
const saved = JSON.parse(fs.readFileSync(context.journalFile, 'utf8'));
// Existing single-channel receipts remain readable; status never creates another post.
if (!saved.targets?.length && saved.postId) {
  const targetFile = context.journalFile.replace('telegram-post-', 'telegram-target-legacy-');
  fs.writeFileSync(targetFile, JSON.stringify({ chatId: context.chatId, messageId: saved.messageId, journalFile: context.journalFile, targetFile, postId: saved.postId, status: saved.status, service: 'tiktok', channelName: 'thieponline.org' }));
  saved.targets = [targetFile];
  fs.writeFileSync(context.journalFile, JSON.stringify(saved));
}
const requests = (saved.targets ?? []).map((file) => JSON.parse(fs.readFileSync(file, 'utf8')))
  .filter((target) => target.postId && (context.queryStatus || ['sending', 'scheduled', 'submitting'].includes(target.status)));
return requests.length ? requests.map((target) => ({ json: { ...target, queryStatus: context.queryStatus, hasStatusRequests: true }, pairedItem: { item: 0 } })) : [{ json: { ...context, hasStatusRequests: false } }];

const resultSource = 'Build Status Requests';
return $input.all().map((item, index) => {
  const context = $(resultSource).itemMatching(index).json;
  const response = item.json;
  const created = response.data?.createPost;
  const post = created ? created.post : response.data?.post;
  const error = response.error ? 'Không xác nhận được kết quả từ API. Không tự gửi lại.' : response.errors?.map((entry) => entry.message).join('\n') ??
    (created && created.__typename !== 'PostActionSuccess' ? created.message ?? created.__typename : post?.error?.message);
  return { json: { ...context, postId: post?.id ?? context.postId, status: response.error || response.errors?.length ? 'unknown' : created && created.__typename !== 'PostActionSuccess' ? 'rejected' : post?.status ?? 'unknown', externalLink: post?.externalLink, error }, pairedItem: { item: index } };
});

const name = $input.first().json.params?.fileName;
const match = typeof name === 'string' && /^([a-f0-9]{32})_(\d{13})\.(mp4|mov|webm|jpg|jpeg|png|webp)$/.exec(name);
if (!match || Number(match[2]) <= Date.now()) throw new Error('File không tồn tại hoặc link đã hết hạn.');
const mimeTypes = { mp4: 'video/mp4', mov: 'video/quicktime', webm: 'video/webm', jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };
return [{ json: { localFile: `/files/${name}`, mimeType: mimeTypes[match[3]] } }];
